def validate_and_write():
    print(f"Validating NLE topics: count = {len(NLE_TOPICS)}")
    assert len(NLE_TOPICS) == 100, f"Expected 100 NLE topics, got {len(NLE_TOPICS)}"
    for idx, t in enumerate(NLE_TOPICS):
        title, subj, sys_name, hallmark, ref_l, ref_u = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at NLE #{idx}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} at NLE #{idx}: {title}"
        assert len(title) > 0 and len(hallmark) > 0, f"Empty title or hallmark at NLE #{idx}"
        assert ref_u.startswith("https://"), f"Invalid ref URL at NLE #{idx}: {ref_u}"
    print("  -> All 100 NLE topics PASSED validation!")

    print(f"Validating MRCEM topics: count = {len(MRCEM_TOPICS)}")
    assert len(MRCEM_TOPICS) == 100, f"Expected 100 MRCEM topics, got {len(MRCEM_TOPICS)}"
    for idx, t in enumerate(MRCEM_TOPICS):
        title, subj, sys_name, hallmark, ref_l, ref_u = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at MRCEM #{idx}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} at MRCEM #{idx}: {title}"
        assert len(title) > 0 and len(hallmark) > 0, f"Empty title or hallmark at MRCEM #{idx}"
        assert ref_u.startswith("https://"), f"Invalid ref URL at MRCEM #{idx}: {ref_u}"
    print("  -> All 100 MRCEM topics PASSED validation!")

    # Write output to scripts/mega87_topics_a.py
    out_path = os.path.join(os.path.dirname(__file__), "mega87_topics_a.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Generated Mega-Batch 87 Part A Topics (NLE & MRCEM)\n\n")
        f.write(f"NLE_TOPICS = {repr(NLE_TOPICS)}\n\n")
        f.write(f"MRCEM_TOPICS = {repr(MRCEM_TOPICS)}\n")
    print(f"Successfully generated {out_path} with 200 topics!")

if __name__ == "__main__":
    validate_and_write()
